package android.media;import java.util.*;import android.graphics.Bitmap;public class MediaMetadata{public static final String METADATA_KEY_ART="android.media.metadata.ART",METADATA_KEY_ALBUM_ART="android.media.metadata.ALBUM_ART";final Map<String,Object> values;MediaMetadata(Map<String,Object> m){values=new HashMap<>(m);}public Bitmap getBitmap(String k){return (Bitmap)values.get(k);}public String getString(String k){return (String)values.get(k);}public long getLong(String k){return ((Number)values.get(k)).longValue();}public static class Builder{final Map<String,Object> m=new HashMap<>();public Builder(){}public Builder(MediaMetadata original){m.putAll(original.values);}public Builder putBitmap(String k,Bitmap b){m.put(k,b);return this;}public Builder putString(String k,String v){m.put(k,v);return this;}public Builder putLong(String k,long v){m.put(k,v);return this;}public MediaMetadata build(){return new MediaMetadata(m);}}}
